#!/usr/bin/env python3
from pathlib import Path
import sys

ROOT = Path.cwd()
APP = ROOT / "src" / "app"
DOC = ROOT / "docs" / "THRIVE_MY_PROGRAM_V0_1_REVIEW_CANDIDATE.md"
ROUTE = APP / "my-program-candidate" / "page.tsx"

if not APP.exists():
    sys.exit("Run this from the thrive-stability-platform repository root.")

inspection_targets = [
    APP / "page.tsx",
    APP / "ThriveNavigation.tsx",
    APP / "ThriveSidebar.tsx",
    APP / "DashboardProgramScope.tsx",
    APP / "DashboardWorkspaceScope.tsx",
    APP / "ProgramContextPanel.tsx",
    APP / "supported-person-program-summary-probe" / "page.tsx",
    APP / "supported-person-program-negative-tests" / "page.tsx",
]

def summarize_file(path: Path) -> str:
    if not path.exists():
        return f"- `{path.relative_to(ROOT)}`: not present"
    text = path.read_text(encoding="utf-8")
    lines = text.splitlines()
    markers = []
    for marker in [
        "programs",
        "program_participants",
        "supabase",
        "ThriveNavigation",
        "ThriveSidebar",
        "DashboardProgramScope",
        "workspace",
        "navigation",
        "href=",
    ]:
        count = text.count(marker)
        if count:
            markers.append(f"{marker}={count}")
    marker_text = ", ".join(markers) if markers else "no selected markers"
    return (
        f"- `{path.relative_to(ROOT)}`: present, {len(lines)} lines; "
        f"{marker_text}"
    )

inspection_summary = "\n".join(summarize_file(path) for path in inspection_targets)

route = '"use client";\n\nimport { useEffect, useMemo, useState } from "react";\nimport { supabase } from "@/lib/supabaseClient";\n\ntype SupportedPersonRow = {\n  id: string;\n  workspace_id: string;\n  preferred_name: string | null;\n  display_name: string;\n  status: string;\n};\n\ntype ParticipationRow = {\n  id: string;\n  workspace_id: string;\n  program_id: string;\n  supported_person_id: string;\n  participant_role: string;\n  status: string;\n};\n\ntype ProgramRow = {\n  id: string;\n  workspace_id: string;\n  program_name: string;\n  program_type: string;\n  status: string;\n  description: string | null;\n};\n\nexport default function MyProgramCandidatePage() {\n  const [email, setEmail] = useState("");\n  const [sessionChecked, setSessionChecked] = useState(false);\n  const [loading, setLoading] = useState(true);\n  const [person, setPerson] = useState<SupportedPersonRow | null>(null);\n  const [participation, setParticipation] =\n    useState<ParticipationRow | null>(null);\n  const [program, setProgram] = useState<ProgramRow | null>(null);\n  const [errorMessage, setErrorMessage] = useState("");\n\n  useEffect(() => {\n    let mounted = true;\n\n    async function loadMyProgram() {\n      const { data: sessionData, error: sessionError } =\n        await supabase.auth.getSession();\n\n      if (!mounted) return;\n\n      const user = sessionData.session?.user ?? null;\n      setSessionChecked(true);\n\n      if (sessionError || !user) {\n        setLoading(false);\n        setErrorMessage(\n          sessionError?.message ?? "Sign in to view your program.",\n        );\n        return;\n      }\n\n      setEmail(user.email ?? "");\n\n      const personResponse = await supabase\n        .from("supported_people")\n        .select("id, workspace_id, preferred_name, display_name, status")\n        .eq("auth_user_id", user.id)\n        .eq("status", "active")\n        .maybeSingle();\n\n      if (!mounted) return;\n\n      if (personResponse.error) {\n        setLoading(false);\n        setErrorMessage(personResponse.error.message);\n        return;\n      }\n\n      if (!personResponse.data) {\n        setLoading(false);\n        return;\n      }\n\n      const personRow = personResponse.data as SupportedPersonRow;\n      setPerson(personRow);\n\n      const participationResponse = await supabase\n        .from("program_participants")\n        .select(\n          "id, workspace_id, program_id, supported_person_id, participant_role, status",\n        )\n        .eq("supported_person_id", personRow.id)\n        .eq("workspace_id", personRow.workspace_id)\n        .eq("status", "active")\n        .order("created_at", { ascending: true })\n        .limit(1)\n        .maybeSingle();\n\n      if (!mounted) return;\n\n      if (participationResponse.error) {\n        setLoading(false);\n        setErrorMessage(participationResponse.error.message);\n        return;\n      }\n\n      if (!participationResponse.data) {\n        setLoading(false);\n        return;\n      }\n\n      const participationRow =\n        participationResponse.data as ParticipationRow;\n      setParticipation(participationRow);\n\n      const programResponse = await supabase\n        .from("programs")\n        .select(\n          "id, workspace_id, program_name, program_type, status, description",\n        )\n        .eq("id", participationRow.program_id)\n        .eq("workspace_id", participationRow.workspace_id)\n        .eq("status", "active")\n        .maybeSingle();\n\n      if (!mounted) return;\n\n      if (programResponse.error) {\n        setLoading(false);\n        setErrorMessage(programResponse.error.message);\n        return;\n      }\n\n      setProgram((programResponse.data as ProgramRow | null) ?? null);\n      setLoading(false);\n    }\n\n    void loadMyProgram();\n\n    return () => {\n      mounted = false;\n    };\n  }, []);\n\n  const participantName = useMemo(\n    () => person?.preferred_name ?? person?.display_name ?? "Participant",\n    [person],\n  );\n\n  if (!sessionChecked || loading) {\n    return (\n      <main className="min-h-screen bg-slate-50 p-6 text-slate-950">\n        <section className="mx-auto max-w-5xl rounded-3xl bg-white p-8 shadow-sm">\n          Loading your program.\n        </section>\n      </main>\n    );\n  }\n\n  if (errorMessage) {\n    return (\n      <main className="min-h-screen bg-slate-50 p-6 text-slate-950">\n        <section className="mx-auto max-w-5xl rounded-3xl border border-red-200 bg-red-50 p-8">\n          <h1 className="text-3xl font-black">My Program</h1>\n          <p className="mt-4 text-red-950">\n            Your program summary could not be loaded.\n          </p>\n          <p className="mt-2 text-sm text-red-800">{errorMessage}</p>\n        </section>\n      </main>\n    );\n  }\n\n  if (!person || !participation || !program) {\n    return (\n      <main className="min-h-screen bg-slate-50 p-6 text-slate-950">\n        <section className="mx-auto max-w-5xl space-y-6">\n          <header className="rounded-3xl bg-white p-8 shadow-sm">\n            <p className="text-xs font-black uppercase tracking-wide text-emerald-700">\n              DSS Enterprises\n            </p>\n            <h1 className="mt-2 text-4xl font-black">My Program</h1>\n            <p className="mt-4 text-slate-600">\n              No active participant-linked program is available for this\n              account.\n            </p>\n          </header>\n\n          <section className="rounded-3xl border border-emerald-100 bg-emerald-50 p-6">\n            <p className="font-black">Signed-in account</p>\n            <p className="mt-2 break-all text-sm">{email}</p>\n          </section>\n\n          <section className="rounded-3xl bg-slate-950 p-6 text-white">\n            <p className="font-black text-emerald-300">Candidate boundary</p>\n            <p className="mt-3 text-sm leading-6">\n              Review-only participant interface. No program creation, update,\n              membership, financial data, Trust Engine control, service-role\n              path, or administrative action is available.\n            </p>\n          </section>\n        </section>\n      </main>\n    );\n  }\n\n  return (\n    <main className="min-h-screen bg-slate-50 p-6 text-slate-950">\n      <section className="mx-auto max-w-5xl space-y-6">\n        <header className="rounded-3xl bg-white p-8 shadow-sm">\n          <p className="text-xs font-black uppercase tracking-wide text-emerald-700">\n            DSS Enterprises\n          </p>\n          <h1 className="mt-2 text-4xl font-black">My Program</h1>\n          <p className="mt-4 max-w-3xl text-slate-600">\n            A clear summary of the active program connected to your\n            participation.\n          </p>\n        </header>\n\n        <section className="rounded-3xl border border-emerald-100 bg-emerald-50 p-6">\n          <p className="text-sm font-black uppercase tracking-wide text-emerald-800">\n            Welcome\n          </p>\n          <p className="mt-2 text-2xl font-black">{participantName}</p>\n          <p className="mt-2 text-sm text-slate-700">{email}</p>\n        </section>\n\n        <section className="rounded-3xl bg-white p-8 shadow-sm">\n          <div className="flex flex-wrap items-start justify-between gap-4">\n            <div>\n              <p className="text-sm font-black uppercase tracking-wide text-emerald-700">\n                Active program\n              </p>\n              <h2 className="mt-2 text-3xl font-black">\n                {program.program_name}\n              </h2>\n            </div>\n            <span className="rounded-full bg-emerald-100 px-4 py-2 text-sm font-black text-emerald-900">\n              {program.status}\n            </span>\n          </div>\n\n          <p className="mt-6 max-w-3xl leading-7 text-slate-700">\n            {program.description ??\n              "A participant-safe program description is not available yet."}\n          </p>\n\n          <dl className="mt-8 grid gap-4 md:grid-cols-2">\n            <div className="rounded-2xl bg-slate-50 p-5">\n              <dt className="text-xs font-black uppercase tracking-wide text-slate-500">\n                Program type\n              </dt>\n              <dd className="mt-2 text-lg font-black">\n                {program.program_type.replaceAll("_", " ")}\n              </dd>\n            </div>\n            <div className="rounded-2xl bg-slate-50 p-5">\n              <dt className="text-xs font-black uppercase tracking-wide text-slate-500">\n                Program status\n              </dt>\n              <dd className="mt-2 text-lg font-black">{program.status}</dd>\n            </div>\n            <div className="rounded-2xl bg-slate-50 p-5">\n              <dt className="text-xs font-black uppercase tracking-wide text-slate-500">\n                Your role\n              </dt>\n              <dd className="mt-2 text-lg font-black">\n                {participation.participant_role.replaceAll("_", " ")}\n              </dd>\n            </div>\n            <div className="rounded-2xl bg-slate-50 p-5">\n              <dt className="text-xs font-black uppercase tracking-wide text-slate-500">\n                Participation status\n              </dt>\n              <dd className="mt-2 text-lg font-black">\n                {participation.status}\n              </dd>\n            </div>\n          </dl>\n        </section>\n\n        <section className="rounded-3xl bg-slate-950 p-6 text-white">\n          <p className="font-black text-emerald-300">\n            Participant-safe boundary\n          </p>\n          <p className="mt-3 text-sm leading-6">\n            This review candidate shows only the signed-in participant\'s active\n            program and participation summary. It contains no UUID display,\n            raw JSON, other-participant data, workspace administration,\n            financial observations, Trust Engine controls, or write actions.\n          </p>\n        </section>\n      </section>\n    </main>\n  );\n}\n'
doc_template = '# THRIVE My Program v0.1 Review Candidate\n\n## Status\n\nReview-only candidate.\n\nNo navigation integration, database write, SQL execution, RLS change, push, merge, or deployment is performed by this generator.\n\n## Verified Starting State\n\n- Synthetic participant-safe program access validation is complete.\n- Checkpoint commit before this candidate: `835c39a`.\n- W18 and W19 remain deferred.\n- `docs/RENEWING/` remains outside this work.\n- Johnny and the Trust Engine remain frozen.\n\n## Local Source Inspection\n\nThe generator inspected these repository paths:\n\n{inspection_summary}\n\n## Candidate Route\n\n`/my-program-candidate`\n\nThe route is intentionally parked and not linked from the main navigation.\n\n## Read Path\n\nThe candidate uses the authenticated Supabase client and performs:\n\n1. self lookup in `supported_people` by `auth_user_id`\n2. first active self-visible row in `program_participants`\n3. exact active program lookup in `programs`\n\nAll reads depend on the existing authenticated RLS path.\n\n## Participant-Facing Fields\n\n- participant preferred/display name\n- program name\n- program type\n- program status\n- participant role\n- participation status\n- participant-safe program description\n\n## Intentionally Excluded\n\n- UUID display\n- raw JSON\n- workspace administration\n- other participants\n- creator fields\n- financial observations\n- Trust Engine controls\n- create, update, delete, archive, or membership actions\n- service-role access\n\n## Candidate Limitation\n\nThe current schema can support more than one participation, but v0.1 displays the earliest active self-visible participation only.\n\nThis is a deliberate small-scope candidate. Multi-program selection is not included.\n\n## Review Matrix\n\n### Person D\n\nExpected:\n\n- My Program loads\n- shared controlled synthetic program is visible\n- active participant role/status are visible\n- no UUIDs or raw JSON appear\n\n### Person A\n\nExpected:\n\n- My Program loads\n- shared controlled synthetic program is visible\n- active participant role/status are visible\n\n### Outsider\n\nExpected:\n\n- no active participant-linked program message\n- no program data appears\n\n### Administrator\n\nNot a participant-facing acceptance actor for v0.1.\n\n## Frozen Boundaries\n\n- no Johnny mutation\n- no Trust Engine synchronization\n- no financial data\n- no service-role use\n- no navigation installation\n- no test-route deletion\n- no W18 or W19 execution\n- no push, merge, or deployment\n\n## Next Gate\n\nBuild and inspect `/my-program-candidate` under Person D, Person A, and outsider.\n\nDo not add it to `ThriveNavigation` or `ThriveSidebar` until the review matrix passes and installation is explicitly approved.\n'
doc = doc_template.format(inspection_summary=inspection_summary)

ROUTE.parent.mkdir(parents=True, exist_ok=True)
DOC.parent.mkdir(parents=True, exist_ok=True)

if ROUTE.exists():
    sys.exit(f"Candidate route already exists: {ROUTE}")

ROUTE.write_text(route, encoding="utf-8")
DOC.write_text(doc, encoding="utf-8")

print(f"Wrote {ROUTE}")
print(f"Wrote {DOC}")
print("Review-only candidate created.")
print("No database request was executed.")
